package stringprograms;

public class Sampleprogram {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		        String s = "Program";  // A string "Program" is stored in variable s
		        for (int i = 0; i < s.length(); i++) { // loop runs from 0 to 6 (because "Program" length = 7)
		            System.out.print(s.charAt(2) + " "); // prints each character at index i
		        }
		    }
		
}
	


